findings.codeql_raw_query:
/**
 * @name Unsafe template compilation from user input
 * @description Compiling templates from untrusted sources can lead to server-side template injection
 * @kind path-problem
 * @problem.severity error
 * @id py/jinja2-template-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module TemplateInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("jinja2").getMember("Environment").getReturn().getMember("from_string").getACall() or
        call = API::moduleImport("jinja2").getMember("Template").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module TemplateInjectionFlow = TaintTracking::Global<TemplateInjectionConfig>;
import TemplateInjectionFlow::PathGraph

from TemplateInjectionFlow::PathNode source, TemplateInjectionFlow::PathNode sink
where TemplateInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Template injection vulnerability from $@.", source.getNode(), "user input"
